(window.__qhadithX=window.__qhadithX||{})[51]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3286","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3286","x":"Narrated Anas:\n\n\"The people of Makkah asked the Prophet (ﷺ) for a sign, so the moon was cleft asunder in Makkah two times (meaning two parts), so the following was revealed: 'The Hour has drawn near, and the moon has been cleft asunder, up to his saying: 'Magic, Mustamir (54:1 & 2)' meaning 'Going away.'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، قَالَ سَأَلَ أَهْلُ مَكَّةَ النَّبِيَّ صلى الله عليه وسلم آيَةً فَانْشَقَّ الْقَمَرُ بِمَكَّةَ مَرَّتَيْنِ فَنَزَلَت ‏:‏ ‏(‏اقتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏سحْرٌ مُسْتَمِرٌّ ‏)‏ يَقُولُ ذَاهِبٌ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"2":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3286","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3286","x":"Narrated Anas:\n\n\"The people of Makkah asked the Prophet (ﷺ) for a sign, so the moon was cleft asunder in Makkah two times (meaning two parts), so the following was revealed: 'The Hour has drawn near, and the moon has been cleft asunder, up to his saying: 'Magic, Mustamir (54:1 & 2)' meaning 'Going away.'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، قَالَ سَأَلَ أَهْلُ مَكَّةَ النَّبِيَّ صلى الله عليه وسلم آيَةً فَانْشَقَّ الْقَمَرُ بِمَكَّةَ مَرَّتَيْنِ فَنَزَلَت ‏:‏ ‏(‏اقتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏سحْرٌ مُسْتَمِرٌّ ‏)‏ يَقُولُ ذَاهِبٌ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"17":[{"c":"Sunan Abu Dawud","r":"Hadith 1322","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1322","x":"Anas said (explaining the meaning) of the following Qur'anic verse \"They used to sleep but little of the night\" (51:17):\n\nThey (the people) used to pray between the Maghrib and 'Isha. The version of Yahya adds: The verse tatajafa junubuhum also means so.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، وَابْنُ أَبِي عَدِيٍّ، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، فِي قَوْلِهِ جَلَّ وَعَزَّ ‏{‏ كَانُوا قَلِيلاً مِنَ اللَّيْلِ مَا يَهْجَعُونَ ‏}‏ قَالَ ‏:‏ كَانُوا يُصَلُّونَ فِيمَا بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، زَادَ فِي حَدِيثِ يَحْيَى ‏:‏ وَكَذَلِكَ ‏{‏ تَتَجَافَى جُنُوبُهُمْ ‏}‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 1327","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1327","x":"Narrated Abdullah ibn Abbas:\n\nThe Prophet's (ﷺ) recitation was loud enough for one who was in the inner chamber to hear it when he was in the house.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرْكَانِيُّ، حَدَّثَنَا ابْنُ أَبِي الزِّنَادِ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، مَوْلَى الْمُطَّلِبِ عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ ‏:‏ كَانَتْ قِرَاءَةُ النَّبِيِّ صلى الله عليه وسلم عَلَى قَدْرِ مَا يَسْمَعُهُ مَنْ فِي الْحُجْرَةِ وَهُوَ فِي الْبَيْتِ ‏.‏","v":[]}],"41":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3273","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3273","x":"Narrated Abu Wa'il:\n\nfrom a man of Rabi'ah who said: \"I arrived in Al-Madinah, entered upon the Messenger of Allah (ﷺ) and mentioned the emissary of 'Ad to him. I said: 'I seek refuge in Allah from being like the emissary of 'Ad.' So the Messenger of Allah (ﷺ) said: 'And what of the emissary of 'Ad?'\" He said: \"I said: You have got the one who is informed about it. When 'Ad suffered from famine they sent Qail and he stayed with Bakr bin Mu'awiyah. He gave him wine to drink and two slave girls to sing for him. Then he went out towards the mountains of Murrah and said: \"O Allah! I did not come to You to cure a sick person, nor to ransom a captive! So give water to Your slave as You used to do, and give water to Bakr bin Mu'awiyah along with him.\" He said that out of gratitude for the wine which he gave him to drink. So two clouds appeared and it was said to him: \"Choose one of them.\" So he chose the black one. It was said to him: \"Take it as ashes that will leave none in 'Ad.\" So he mentioned that the wind sent upon them was not more than this circle - meaning the circle of a ring - then he recited: \"...We sent against them the barren wind; it spared nothing that it reached, but blew it into broken spreads of rotten ruins. (51:41 & 42)\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ سَلاَّمٍ، عَنْ عَاصِمِ بْنِ أَبِي النَّجُودِ، عَنْ أَبِي وَائِلٍ، عَنْ رَجُلٍ، مِنْ رَبِيعَةَ قَالَ قَدِمْتُ الْمَدِينَةَ فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَذُكِرْتُ عِنْدَهُ وَافِدَ عَادٍ فَقُلْتُ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِثْلَ وَافِدِ عَادٍ ‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ وَمَا وَافِدُ عَادٍ ‏\"‏ ‏.‏ قَالَ فَقُلْتُ عَلَى الْخَبِيرِ سَقَطْتَ إِنَّ عَادًا لَمَّا أُقْحِطَتْ بَعَثَتْ قَيْلاً فَنَزَلَ عَلَى بَكْرِ بْنِ مُعَاوِيَةَ فَسَقَاهُ الْخَمْرَ وَغَنَّتْهُ الْجَرَادَتَانِ ثُمَّ خَرَجَ يُرِيدُ جِبَالَ مَهْرَةَ فَقَالَ اللَّهُمَّ إِنِّي لَمْ آتِكَ لِمَرِيضٍ فَأُدَاوِيَهِ وَلاَ لأَسِيرٍ فَأُفَادِيَهُ فَاسْقِ عَبْدَكَ مَا كُنْتَ مُسْقِيَهُ وَاسْقِ مَعَهُ بَكْرَ بْنَ مُعَاوِيَةَ ‏.‏ يَشْكُرْ لَهُ الْخَمْرَ الَّذِي سَقَاهُ فَرُفِعَ لَهُ سَحَابَاتٌ فَقِيلَ لَهُ اخْتَرْ إِحْدَاهُنَّ فَاخْتَارَ السَّوْدَاءَ مِنْهُنَّ فَقِيلَ لَهُ خُذْهَا رَمَادًا رَمْدَدًا لاَ تَذَرُ مِنْ عَادٍ أَحَدًا وَذُكِرَ أَنَّهُ لَمْ يُرْسَلْ عَلَيْهِمْ مِنَ الرِّيحِ إِلاَّ قَدْرُ هَذِهِ الْحَلْقَةِ يَعْنِي حَلْقَةَ الْخَاتَمِ ‏.‏ ثُمَّ قَرَأَ ‏:‏ ‏(‏إذْ أَرْسَلْنَا عَلَيْهِمُ الرِّيحَ الْعَقِيمَ * مَا تَذَرُ مِنْ شَيْءٍ أَتَتْ عَلَيْهِ إِلاَّ جَعَلَتْهُ كَالرَّمِيمِ ‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى غَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ سَلاَّمٍ أَبِي الْمُنْذِرِ عَنْ عَاصِمِ بْنِ أَبِي النَّجُودِ عَنْ أَبِي وَائِلٍ عَنِ الْحَارِثِ بْنِ حَسَّانَ وَيُقَالُ لَهُ الْحَارِثُ بْنُ يَزِيدَ ‏.‏","v":[]}],"58":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 43, Hadith 2940","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-43/Hadith-2940","x":"Narrated 'Abdullah:\n\n\"The Messenger of Allah (ﷺ) recited to me: \"Indeed Allah is the Provider, The Possessor of power, the Firm.\" (51:58)","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، قَالَ حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ أَقْرَأَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم‏:‏‏(‏ إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}]};